#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$ROOT_DIR"

APK="${1:-app/build/outputs/apk/release/app-release.apk}"

# phase3-review-check.sh allowlists permissions in the SOURCE manifest. That manifest is not what
# ships: the merged one also carries everything a dependency declares, and those reach the installed
# app without ever appearing in a file a reviewer reads. This gate closes that hole by comparing the
# built artefact against the source set plus the four library permissions that are individually
# justified below. A dependency that starts declaring a new permission fails here, not in the
# Play Console.
[ -f "$APK" ] || { printf 'FAIL: %s not found (run assembleRelease first)\n' "$APK" >&2; exit 1; }

AAPT2="$(find "$ANDROID_HOME/build-tools" -name aapt2 -type f 2>/dev/null | sort | tail -1)"
[ -n "$AAPT2" ] || { echo "FAIL: aapt2 not found in ANDROID_HOME/build-tools" >&2; exit 1; }

BADGING="$("$AAPT2" dump badging "$APK")"

printf '%s\n' "$BADGING" \
  | sed -n "s/^uses-permission: name='\([^']*\)'.*/\1/p" \
  | sort -u > /tmp/merged-permissions.txt

grep -oE '<uses-permission[^>]*android:name="[^"]+"' app/src/main/AndroidManifest.xml \
  | grep -oE 'android:name="[^"]+"' | sed 's/android:name="//;s/"$//' \
  | sort -u > /tmp/source-permissions.txt

# Each line here is a permission the app does not declare but an installed dependency does.
# Anything not listed is unexpected, so this list can only grow through a visible decision.
cat > /tmp/library-permissions.txt <<'LIB'
android.permission.USE_BIOMETRIC
android.permission.USE_FINGERPRINT
com.android.vending.BILLING
com.shieldra.app.DYNAMIC_RECEIVER_NOT_EXPORTED_PERMISSION
LIB

# Justification, kept with the gate that enforces it:
#   USE_BIOMETRIC / USE_FINGERPRINT — androidx.biometric:1.1.0, the owner gate in OwnerCheck.kt.
#   com.android.vending.BILLING     — Play Billing 9.1.0, the Pro tier (amendment A-40).
#   DYNAMIC_RECEIVER_NOT_EXPORTED   — generated by ContextCompat.registerReceiver(..., NOT_EXPORTED),
#                                     which the protection service's battery and shutdown receivers use.
{ cat /tmp/source-permissions.txt; cat /tmp/library-permissions.txt; } | sort -u > /tmp/expected-permissions.txt

if diff -u /tmp/expected-permissions.txt /tmp/merged-permissions.txt > /tmp/permission-diff.txt; then
    printf 'PASS: the installed APK declares exactly the reviewed permission set (%s permissions)\n' \
        "$(wc -l < /tmp/merged-permissions.txt | tr -d ' ')"
    printf '      %s declared by the app, %s contributed by libraries\n' \
        "$(wc -l < /tmp/source-permissions.txt | tr -d ' ')" "$(wc -l < /tmp/library-permissions.txt | tr -d ' ')"
    exit 0
fi

echo "FAIL: the built APK does not match the reviewed permission set." >&2
echo "--- expected (source manifest + library allowlist) vs actual (merged manifest) ---" >&2
cat /tmp/permission-diff.txt >&2
exit 1
